#' Calculate UK Multiple Traffic Light (MTL) Front-of-Pack Nutrition Labels
#'
#' Evaluates food and drink products according to the official UK Department of Health
#' and Social Care (DHSC), Food Standards Agency (FSA), and devolved administrations'
#' Front-of-Pack (FoP) Multiple Traffic Light guidance (2013, updated 2016).
#'
#' The UK Front-of-Pack traffic light labelling scheme applies color codes
#' (\strong{Green} / Low, \strong{Amber} / Medium, \strong{Red} / High) to four
#' key nutrients of public health concern:
#' \itemize{
#'   \item Total Fat
#'   \item Saturated Fatty Acids (Saturates)
#'   \item Total Sugars
#'   \item Salt (or Sodium converted to salt)
#' }
#'
#' \strong{Criteria for Foods (per 100g):}
#' \itemize{
#'   \item \strong{Fat}: Green \eqn{\le 3.0\text{g}}, Amber \eqn{> 3.0\text{g}} and \eqn{\le 17.5\text{g}}, Red \eqn{> 17.5\text{g}} (or \eqn{> 21\text{g/portion}} when portion \eqn{> 100\text{g}}).
#'   \item \strong{Saturates}: Green \eqn{\le 1.5\text{g}}, Amber \eqn{> 1.5\text{g}} and \eqn{\le 5.0\text{g}}, Red \eqn{> 5.0\text{g}} (or \eqn{> 6.0\text{g/portion}} when portion \eqn{> 100\text{g}}).
#'   \item \strong{Sugars}: Green \eqn{\le 5.0\text{g}}, Amber \eqn{> 5.0\text{g}} and \eqn{\le 22.5\text{g}}, Red \eqn{> 22.5\text{g}} (or \eqn{> 27.0\text{g/portion}} when portion \eqn{> 100\text{g}}).
#'   \item \strong{Salt}: Green \eqn{\le 0.3\text{g}}, Amber \eqn{> 0.3\text{g}} and \eqn{\le 1.5\text{g}}, Red \eqn{> 1.5\text{g}} (or \eqn{> 1.8\text{g/portion}} when portion \eqn{> 100\text{g}}).
#' }
#'
#' \strong{Criteria for Drinks (per 100ml):}
#' \itemize{
#'   \item \strong{Fat}: Green \eqn{\le 1.5\text{g}}, Amber \eqn{> 1.5\text{g}} and \eqn{\le 8.75\text{g}}, Red \eqn{> 8.75\text{g}} (or \eqn{> 10.5\text{g/portion}} when portion \eqn{> 150\text{ml}}).
#'   \item \strong{Saturates}: Green \eqn{\le 0.75\text{g}}, Amber \eqn{> 0.75\text{g}} and \eqn{\le 2.5\text{g}}, Red \eqn{> 2.5\text{g}} (or \eqn{> 3.0\text{g/portion}} when portion \eqn{> 150\text{ml}}).
#'   \item \strong{Sugars}: Green \eqn{\le 2.5\text{g}}, Amber \eqn{> 2.5\text{g}} and \eqn{\le 11.25\text{g}}, Red \eqn{> 11.25\text{g}} (or \eqn{> 13.5\text{g/portion}} when portion \eqn{> 150\text{ml}}).
#'   \item \strong{Salt}: Green \eqn{\le 0.3\text{g}}, Amber \eqn{> 0.3\text{g}} and \eqn{\le 0.75\text{g}}, Red \eqn{> 0.75\text{g}} (or \eqn{> 0.9\text{g/portion}} when portion \eqn{> 150\text{ml}}).
#' }
#'
#' @param fat_g Numeric vector of total fat in grams (g) per 100g/ml.
#' @param sat_fat_g Numeric vector of saturated fat in grams (g) per 100g/ml.
#' @param sugars_g Numeric vector of total sugars in grams (g) per 100g/ml.
#' @param salt_g Numeric vector of salt in grams (g) per 100g/ml. If \code{NULL},
#'   calculated from \code{sodium_mg}.
#' @param sodium_mg Optional numeric vector of sodium in milligrams (mg) per 100g/ml.
#' @param portion_g Optional numeric vector of portion / serving size in grams (or ml).
#' @param fat_portion_g Optional numeric vector of fat per portion. If \code{NULL}
#'   and \code{portion_g} is supplied, computed automatically as \code{fat_g * portion_g / 100}.
#' @param sat_fat_portion_g Optional numeric vector of saturated fat per portion.
#' @param sugars_portion_g Optional numeric vector of total sugars per portion.
#' @param salt_portion_g Optional numeric vector of salt per portion.
#' @param is_drink Logical vector indicating whether the product is a drink/liquid
#'   (\code{TRUE}) or a solid food (\code{FALSE}). Default is \code{FALSE}.
#'
#' @return A \code{data.frame} containing:
#' \describe{
#'   \item{fat_colour}{Colour code for fat (\code{"Green"}, \code{"Amber"}, \code{"Red"}).}
#'   \item{sat_fat_colour}{Colour code for saturated fat.}
#'   \item{sugars_colour}{Colour code for total sugars.}
#'   \item{salt_colour}{Colour code for salt.}
#'   \item{n_green}{Count of green lights (0 to 4).}
#'   \item{n_amber}{Count of amber lights (0 to 4).}
#'   \item{n_red}{Count of red lights (0 to 4).}
#'   \item{has_red}{Logical indicating whether the item has at least one Red light.}
#'   \item{all_green}{Logical indicating whether all four lights are Green.}
#'   \item{mtl_healthiness}{Classification: \code{"healthier"} (0 red lights) or \code{"less healthy"} (\eqn{\ge 1} red lights), following public health research standards (Tan et al., 2025).}
#' }
#'
#' @references
#' Department of Health, Food Standards Agency, Welsh Government, and Food Standards Scotland (2016).
#' \emph{Guide to creating a front of pack (FoP) nutrition label for pre-packed products sold through retail outlets}.
#' \url{https://www.gov.uk/government/publications/front-of-pack-nutrition-labelling-guidance}
#'
#' Tan M, Pham H, Pombo-Rodrigues S, et al. (2025). Nutritional composition and healthiness of out-of-home food and drink.
#' \emph{Proceedings of the Nutrition Society}, 84(OCE3), E208.
#'
#' @examples
#' # Solid food example (e.g. snack bar):
#' calculate_mtl(
#'   fat_g = 18.0,
#'   sat_fat_g = 4.2,
#'   sugars_g = 24.0,
#'   salt_g = 0.5,
#'   portion_g = 60
#' )
#'
#' # Large portion food triggering per-portion Red threshold:
#' # 120g portion with 16g/100g fat -> portion fat = 19.2g (<21g cap)
#' # 150g portion with 16g/100g fat -> portion fat = 24.0g (>21g cap -> Red!)
#' calculate_mtl(
#'   fat_g = 16.0,
#'   sat_fat_g = 3.0,
#'   sugars_g = 10.0,
#'   salt_g = 0.8,
#'   portion_g = 150
#' )
#'
#' @export
calculate_mtl <- function(fat_g = 0,
                          sat_fat_g = 0,
                          sugars_g = 0,
                          salt_g = NULL,
                          sodium_mg = NULL,
                          portion_g = NULL,
                          fat_portion_g = NULL,
                          sat_fat_portion_g = NULL,
                          sugars_portion_g = NULL,
                          salt_portion_g = NULL,
                          is_drink = FALSE) {
  # Determine vector length
  lens <- c(
    length(fat_g),
    length(sat_fat_g),
    length(sugars_g),
    if (!is.null(salt_g)) length(salt_g) else 0,
    if (!is.null(sodium_mg)) length(sodium_mg) else 0,
    if (!is.null(portion_g)) length(portion_g) else 0,
    length(is_drink)
  )
  n <- max(lens, 1)

  fat_g <- rep_len(as.numeric(fat_g), n)
  sat_fat_g <- rep_len(as.numeric(sat_fat_g), n)
  sugars_g <- rep_len(as.numeric(sugars_g), n)
  is_drink <- rep_len(as.logical(is_drink), n)

  fat_g[is.na(fat_g)] <- 0
  sat_fat_g[is.na(sat_fat_g)] <- 0
  sugars_g[is.na(sugars_g)] <- 0
  is_drink[is.na(is_drink)] <- FALSE

  # Salt vs Sodium
  if (is.null(salt_g)) {
    if (is.null(sodium_mg)) {
      salt_g <- rep_len(0, n)
    } else {
      sodium_mg <- rep_len(as.numeric(sodium_mg), n)
      sodium_mg[is.na(sodium_mg)] <- 0
      salt_g <- sodium_mg * 2.5 / 1000
    }
  } else {
    salt_g <- rep_len(as.numeric(salt_g), n)
    salt_g[is.na(salt_g)] <- 0
  }

  # Portion calculations
  has_portion <- !is.null(portion_g)
  if (has_portion) {
    portion_g <- rep_len(as.numeric(portion_g), n)
    if (is.null(fat_portion_g)) fat_portion_g <- fat_g * portion_g / 100
    if (is.null(sat_fat_portion_g)) sat_fat_portion_g <- sat_fat_g * portion_g / 100
    if (is.null(sugars_portion_g)) sugars_portion_g <- sugars_g * portion_g / 100
    if (is.null(salt_portion_g)) salt_portion_g <- salt_g * portion_g / 100
  }

  if (!is.null(fat_portion_g)) fat_portion_g <- rep_len(as.numeric(fat_portion_g), n)
  if (!is.null(sat_fat_portion_g)) sat_fat_portion_g <- rep_len(as.numeric(sat_fat_portion_g), n)
  if (!is.null(sugars_portion_g)) sugars_portion_g <- rep_len(as.numeric(sugars_portion_g), n)
  if (!is.null(salt_portion_g)) salt_portion_g <- rep_len(as.numeric(salt_portion_g), n)

  # Initialize colours
  fat_col <- character(n)
  sat_fat_col <- character(n)
  sugars_col <- character(n)
  salt_col <- character(n)

  for (i in seq_len(n)) {
    if (!is_drink[i]) {
      # SOLID FOODS
      # Fat: Green <= 3.0, Amber > 3.0 & <= 17.5, Red > 17.5
      f_val <- fat_g[i]
      if (f_val <= 3.0) {
        fat_col[i] <- "Green"
      } else if (f_val <= 17.5) {
        fat_col[i] <- "Amber"
      } else {
        fat_col[i] <- "Red"
      }
      # Portion cap for Red (>21g/portion when portion > 100g)
      if (!is.null(portion_g) && !is.na(portion_g[i]) && portion_g[i] > 100) {
        if (!is.null(fat_portion_g) && !is.na(fat_portion_g[i]) && fat_portion_g[i] > 21.0) {
          fat_col[i] <- "Red"
        }
      }

      # Sat Fat: Green <= 1.5, Amber > 1.5 & <= 5.0, Red > 5.0
      sf_val <- sat_fat_g[i]
      if (sf_val <= 1.5) {
        sat_fat_col[i] <- "Green"
      } else if (sf_val <= 5.0) {
        sat_fat_col[i] <- "Amber"
      } else {
        sat_fat_col[i] <- "Red"
      }
      # Portion cap for Red (>6.0g/portion when portion > 100g)
      if (!is.null(portion_g) && !is.na(portion_g[i]) && portion_g[i] > 100) {
        if (!is.null(sat_fat_portion_g) && !is.na(sat_fat_portion_g[i]) && sat_fat_portion_g[i] > 6.0) {
          sat_fat_col[i] <- "Red"
        }
      }

      # Total Sugars: Green <= 5.0, Amber > 5.0 & <= 22.5, Red > 22.5
      sug_val <- sugars_g[i]
      if (sug_val <= 5.0) {
        sugars_col[i] <- "Green"
      } else if (sug_val <= 22.5) {
        sugars_col[i] <- "Amber"
      } else {
        sugars_col[i] <- "Red"
      }
      # Portion cap for Red (>27.0g/portion when portion > 100g)
      if (!is.null(portion_g) && !is.na(portion_g[i]) && portion_g[i] > 100) {
        if (!is.null(sugars_portion_g) && !is.na(sugars_portion_g[i]) && sugars_portion_g[i] > 27.0) {
          sugars_col[i] <- "Red"
        }
      }

      # Salt: Green <= 0.3, Amber > 0.3 & <= 1.5, Red > 1.5
      salt_val <- salt_g[i]
      if (salt_val <= 0.3) {
        salt_col[i] <- "Green"
      } else if (salt_val <= 1.5) {
        salt_col[i] <- "Amber"
      } else {
        salt_col[i] <- "Red"
      }
      # Portion cap for Red (>1.8g/portion when portion > 100g)
      if (!is.null(portion_g) && !is.na(portion_g[i]) && portion_g[i] > 100) {
        if (!is.null(salt_portion_g) && !is.na(salt_portion_g[i]) && salt_portion_g[i] > 1.8) {
          salt_col[i] <- "Red"
        }
      }

    } else {
      # DRINKS / LIQUIDS
      # Fat: Green <= 1.5, Amber > 1.5 & <= 8.75, Red > 8.75
      f_val <- fat_g[i]
      if (f_val <= 1.5) {
        fat_col[i] <- "Green"
      } else if (f_val <= 8.75) {
        fat_col[i] <- "Amber"
      } else {
        fat_col[i] <- "Red"
      }
      # Portion cap for Red (>10.5g/portion when portion > 150ml)
      if (!is.null(portion_g) && !is.na(portion_g[i]) && portion_g[i] > 150) {
        if (!is.null(fat_portion_g) && !is.na(fat_portion_g[i]) && fat_portion_g[i] > 10.5) {
          fat_col[i] <- "Red"
        }
      }

      # Sat Fat: Green <= 0.75, Amber > 0.75 & <= 2.5, Red > 2.5
      sf_val <- sat_fat_g[i]
      if (sf_val <= 0.75) {
        sat_fat_col[i] <- "Green"
      } else if (sf_val <= 2.5) {
        sat_fat_col[i] <- "Amber"
      } else {
        sat_fat_col[i] <- "Red"
      }
      # Portion cap for Red (>3.0g/portion when portion > 150ml)
      if (!is.null(portion_g) && !is.na(portion_g[i]) && portion_g[i] > 150) {
        if (!is.null(sat_fat_portion_g) && !is.na(sat_fat_portion_g[i]) && sat_fat_portion_g[i] > 3.0) {
          sat_fat_col[i] <- "Red"
        }
      }

      # Total Sugars: Green <= 2.5, Amber > 2.5 & <= 11.25, Red > 11.25
      sug_val <- sugars_g[i]
      if (sug_val <= 2.5) {
        sugars_col[i] <- "Green"
      } else if (sug_val <= 11.25) {
        sugars_col[i] <- "Amber"
      } else {
        sugars_col[i] <- "Red"
      }
      # Portion cap for Red (>13.5g/portion when portion > 150ml)
      if (!is.null(portion_g) && !is.na(portion_g[i]) && portion_g[i] > 150) {
        if (!is.null(sugars_portion_g) && !is.na(sugars_portion_g[i]) && sugars_portion_g[i] > 13.5) {
          sugars_col[i] <- "Red"
        }
      }

      # Salt: Green <= 0.3, Amber > 0.3 & <= 0.75, Red > 0.75
      salt_val <- salt_g[i]
      if (salt_val <= 0.3) {
        salt_col[i] <- "Green"
      } else if (salt_val <= 0.75) {
        salt_col[i] <- "Amber"
      } else {
        salt_col[i] <- "Red"
      }
      # Portion cap for Red (>0.9g/portion when portion > 150ml)
      if (!is.null(portion_g) && !is.na(portion_g[i]) && portion_g[i] > 150) {
        if (!is.null(salt_portion_g) && !is.na(salt_portion_g[i]) && salt_portion_g[i] > 0.9) {
          salt_col[i] <- "Red"
        }
      }
    }
  }

  all_cols <- cbind(fat_col, sat_fat_col, sugars_col, salt_col)
  n_red <- rowSums(all_cols == "Red")
  n_amber <- rowSums(all_cols == "Amber")
  n_green <- rowSums(all_cols == "Green")
  has_red <- (n_red > 0)
  all_green <- (n_green == 4)

  healthiness <- ifelse(has_red, "less healthy", "healthier")

  data.frame(
    fat_colour = fat_col,
    sat_fat_colour = sat_fat_col,
    sugars_colour = sugars_col,
    salt_colour = salt_col,
    n_green = n_green,
    n_amber = n_amber,
    n_red = n_red,
    has_red = has_red,
    all_green = all_green,
    mtl_healthiness = healthiness,
    stringsAsFactors = FALSE
  )
}

#' Soft Drinks Industry Levy (SDIL) Classification and Rate
#'
#' Evaluates non-alcoholic beverages against the UK Soft Drinks Industry Levy (SDIL)
#' statutory thresholds.
#'
#' Under the Soft Drinks Industry Levy Regulations 2018, packaged soft drinks
#' containing added sugars are subject to a tiered levy:
#' \itemize{
#'   \item \strong{Exempt}: Less than 5.0g total sugars per 100ml, or products meeting
#'     statutory exemptions (such as 100\% pure fruit juice, milk-based drinks with at
#'     least 75\% milk content, and alcohol-replacement drinks).
#'   \item \strong{Tier 1 (Lower / Standard Rate)}: 5.0g to less than 8.0g total sugars per 100ml.
#'     Originally 18p per litre (updated to 19.4p/L).
#'   \item \strong{Tier 2 (Higher Rate)}: 8.0g or more total sugars per 100ml.
#'     Originally 24p per litre (updated to 25.9p/L).
#' }
#'
#' @param sugars_g_100ml Numeric vector of total sugars in grams per 100ml.
#' @param is_exempt Logical vector indicating whether the drink has a statutory exemption
#'   (e.g., 100\% pure fruit/vegetable juice, \eqn{\ge 75\%} milk drink). Default is \code{FALSE}.
#' @param rate_year Character or numeric specifying the levy fee schedule: \code{"2018"}
#'   (18p / 24p per litre) or \code{"2025"} (19.4p / 25.9p per litre). Default is \code{"2025"}.
#'
#' @return A \code{data.frame} containing:
#' \describe{
#'   \item{sugars_g_100ml}{Total sugars per 100ml.}
#'   \item{is_exempt}{Exemption flag.}
#'   \item{sdil_tier}{Character: \code{"Exempt"}, \code{"Tier 1 (Lower)"}, or \code{"Tier 2 (Higher)"}.}
#'   \item{is_levied}{Logical: \code{TRUE} if subject to the levy, \code{FALSE} if exempt.}
#'   \item{levy_rate_gbp_per_l}{Levy rate in GBP (pounds) per litre.}
#' }
#'
#' @references
#' HM Revenue & Customs (2018). \emph{Soft Drinks Industry Levy: guidance and rates}.
#' \url{https://www.gov.uk/guidance/soft-drinks-industry-levy}
#'
#' @examples
#' calculate_sdil(sugars_g_100ml = c(3.2, 5.5, 9.8, 11.0), is_exempt = c(FALSE, FALSE, FALSE, TRUE))
#'
#' @export
calculate_sdil <- function(sugars_g_100ml,
                           is_exempt = FALSE,
                           rate_year = c("2025", "2018")) {
  rate_year <- as.character(match.arg(rate_year))
  n <- max(length(sugars_g_100ml), length(is_exempt))

  sugars <- rep_len(as.numeric(sugars_g_100ml), n)
  sugars[is.na(sugars)] <- 0

  exempt <- rep_len(as.logical(is_exempt), n)
  exempt[is.na(exempt)] <- FALSE

  # Rates per litre
  t1_rate <- if (rate_year == "2018") 0.18 else 0.194
  t2_rate <- if (rate_year == "2018") 0.24 else 0.259

  tier <- character(n)
  levied <- logical(n)
  rate <- numeric(n)

  for (i in seq_len(n)) {
    if (exempt[i] || sugars[i] < 5.0) {
      tier[i] <- "Exempt"
      levied[i] <- FALSE
      rate[i] <- 0.0
    } else if (sugars[i] < 8.0) {
      tier[i] <- "Tier 1 (Lower)"
      levied[i] <- TRUE
      rate[i] <- t1_rate
    } else {
      tier[i] <- "Tier 2 (Higher)"
      levied[i] <- TRUE
      rate[i] <- t2_rate
    }
  }

  data.frame(
    sugars_g_100ml = sugars,
    is_exempt = exempt,
    sdil_tier = tier,
    is_levied = levied,
    levy_rate_gbp_per_l = rate,
    stringsAsFactors = FALSE
  )
}

#' Check Compliance with UK Salt Reduction Targets
#'
#' Compares product salt content against the UK Office for Health Improvement and
#' Disparities (OHID) and Public Health England (PHE) Salt Reduction Targets for 2024.
#'
#' The UK salt reduction programme defines category-specific \strong{sales-weighted average}
#' targets and \strong{maximum} targets per 100g for pre-packed retail foods, alongside
#' dish and meal per-serving caps for the out-of-home (OOH) sector.
#'
#' @param salt_g_100g Numeric vector of salt in grams (g) per 100g.
#' @param category Character vector of food categories corresponding to OHID salt target categories.
#' @param salt_portion_g Optional numeric vector of salt in grams per portion / serving.
#'   Particularly relevant for out-of-home dish targets.
#' @param target_table Optional custom target lookup table. Defaults to \code{\link{ohid_salt_targets_2024}}.
#'
#' @return A \code{data.frame} matching the input rows with target benchmarks and compliance flags:
#' \describe{
#'   \item{salt_g_100g}{Observed salt per 100g.}
#'   \item{category}{Matched food category.}
#'   \item{target_average_100g}{OHID average target per 100g.}
#'   \item{target_maximum_100g}{OHID maximum target per 100g.}
#'   \item{meets_average}{Logical: \code{TRUE} if salt \eqn{\le} average target.}
#'   \item{meets_maximum}{Logical: \code{TRUE} if salt \eqn{\le} maximum target.}
#'   \item{salt_compliant}{Overall salt target compliance (\code{meets_maximum} if defined, else \code{meets_average}).}
#' }
#'
#' @references
#' Office for Health Improvement and Disparities (2020/2024). \emph{Salt reduction targets for 2024}.
#' \url{https://www.gov.uk/government/publications/salt-reduction-targets-for-2024}
#'
#' @examples
#' # Bread category comparison (average target 0.85g, max target 1.01g):
#' check_salt_target(salt_g_100g = c(0.80, 0.95, 1.20), category = "Bread")
#'
#' @export
check_salt_target <- function(salt_g_100g,
                              category,
                              salt_portion_g = NULL,
                              target_table = NULL) {
  if (is.null(target_table)) {
    target_table <- ohid_salt_targets_2024
  }

  n <- max(length(salt_g_100g), length(category))
  salt <- rep_len(as.numeric(salt_g_100g), n)
  cat_vec <- rep_len(as.character(category), n)

  # Match category case-insensitively
  norm_cats <- tolower(trimws(target_table$category))
  cat_lower <- tolower(trimws(cat_vec))

  idx <- match(cat_lower, norm_cats)

  # Fallback fuzzy matching if exact match not found
  unmatched <- which(is.na(idx))
  for (u in unmatched) {
    if (!is.na(cat_lower[u]) && nzchar(cat_lower[u])) {
      matches <- grep(cat_lower[u], norm_cats, fixed = TRUE)
      if (length(matches) > 0) {
        idx[u] <- matches[1]
      }
    }
  }

  tgt_avg <- target_table$target_average_100g[idx]
  tgt_max <- target_table$target_maximum_100g[idx]

  meets_avg <- ifelse(is.na(tgt_avg), NA, salt <= tgt_avg)
  meets_max <- ifelse(is.na(tgt_max), NA, salt <= tgt_max)

  compliant <- ifelse(!is.na(meets_max), meets_max, meets_avg)

  data.frame(
    salt_g_100g = salt,
    category = cat_vec,
    target_average_100g = tgt_avg,
    target_maximum_100g = tgt_max,
    meets_average = meets_avg,
    meets_maximum = meets_max,
    salt_compliant = compliant,
    stringsAsFactors = FALSE
  )
}

#' Check Compliance with UK Sugar Reduction Programme Targets
#'
#' Compares product sugar content against OHID / PHE Sugar Reduction Programme
#' category targets and maximum portion caps.
#'
#' @param sugars_g_100g Numeric vector of total sugars in grams (g) per 100g.
#' @param category Character vector of product categories (e.g. \code{"Biscuits"}, \code{"Cakes"},
#'   \code{"Chocolate confectionery"}, \code{"Ice cream"}, \code{"Morning goods"},
#'   \code{"Puddings"}, \code{"Yogurts"}, \code{"Breakfast cereals"}, \code{"Sweet spreads"}).
#' @param sugars_portion_g Optional numeric vector of sugar per portion (g).
#' @param target_table Optional custom target lookup table. Defaults to \code{\link{ohid_sugar_targets}}.
#'
#' @return A \code{data.frame} with sugar benchmarks and compliance indicators:
#' \describe{
#'   \item{sugars_g_100g}{Observed sugars per 100g.}
#'   \item{category}{Matched sugar reduction category.}
#'   \item{target_sugars_100g}{OHID sugar reduction target per 100g.}
#'   \item{max_portion_cap_g}{Maximum portion sugar cap (if applicable).}
#'   \item{meets_sugar_target}{Logical indicating compliance with per-100g target.}
#'   \item{meets_portion_cap}{Logical indicating compliance with portion cap (if portion sugar supplied).}
#'   \item{sugar_compliant}{Overall sugar compliance.}
#' }
#'
#' @references
#' Public Health England / Office for Health Improvement and Disparities (2020).
#' \emph{Sugar reduction: industry progress 2015 to 2020}.
#' \url{https://www.gov.uk/government/collections/sugar-reduction}
#'
#' @examples
#' check_sugar_target(sugars_g_100g = c(22.0, 35.0), category = "Biscuits")
#'
#' @export
check_sugar_target <- function(sugars_g_100g,
                               category,
                               sugars_portion_g = NULL,
                               target_table = NULL) {
  if (is.null(target_table)) {
    target_table <- ohid_sugar_targets
  }

  n <- max(length(sugars_g_100g), length(category))
  sugars <- rep_len(as.numeric(sugars_g_100g), n)
  cat_vec <- rep_len(as.character(category), n)

  norm_cats <- tolower(trimws(target_table$category))
  cat_lower <- tolower(trimws(cat_vec))

  idx <- match(cat_lower, norm_cats)
  unmatched <- which(is.na(idx))
  for (u in unmatched) {
    if (!is.na(cat_lower[u]) && nzchar(cat_lower[u])) {
      matches <- grep(cat_lower[u], norm_cats, fixed = TRUE)
      if (length(matches) > 0) idx[u] <- matches[1]
    }
  }

  tgt_sug <- target_table$target_sugars_100g[idx]
  cap_g <- target_table$max_portion_cap_g[idx]

  meets_tgt <- ifelse(is.na(tgt_sug), NA, sugars <= tgt_sug)

  has_portion_sug <- !is.null(sugars_portion_g)
  if (has_portion_sug) {
    p_sug <- rep_len(as.numeric(sugars_portion_g), n)
    meets_cap <- ifelse(is.na(cap_g), TRUE, p_sug <= cap_g)
  } else {
    meets_cap <- rep(NA, n)
  }

  compliant <- ifelse(is.na(meets_cap), meets_tgt, meets_tgt & meets_cap)

  data.frame(
    sugars_g_100g = sugars,
    category = cat_vec,
    target_sugars_100g = tgt_sug,
    max_portion_cap_g = cap_g,
    meets_sugar_target = meets_tgt,
    meets_portion_cap = meets_cap,
    sugar_compliant = compliant,
    stringsAsFactors = FALSE
  )
}

#' Check Compliance with UK Calorie Reduction Guidelines
#'
#' Evaluates meal items, sandwiches, sides, and snacks against UK Calorie Reduction
#' Programme guidelines published by Public Health England / OHID.
#'
#' Frameworks included:
#' \itemize{
#'   \item \strong{400-600-600 Campaign Guidelines}: 400 kcal breakfast, 600 kcal lunch,
#'     600 kcal dinner, plus 200 kcal for drinks and snacks.
#'   \item \strong{Category Single-Serve Guidelines}:
#'     \itemize{
#'       \item Ready meals / meal centres: 550--600 kcal maximum.
#'       \item Sandwiches: 550 kcal maximum.
#'       \item Starters / sides / small plates: 250 kcal maximum.
#'       \item Puddings / desserts: 220--250 kcal maximum.
#'       \item Single-serve pizzas: 1000 kcal maximum (or 650 kcal per portion).
#'     }
#' }
#'
#' @param energy_kcal_portion Numeric vector of energy in kilocalories (kcal) per portion / serving.
#' @param category Optional character vector specifying the food category (e.g. \code{"Sandwiches"},
#'   \code{"Main meal"}, \code{"Pizza"}, \code{"Side"}, \code{"Dessert"}).
#' @param meal_type Character string specifying the meal benchmark: \code{"general"},
#'   \code{"breakfast"} (400 kcal), \code{"lunch"} (600 kcal), \code{"dinner"} (600 kcal),
#'   or \code{"snack"} (200 kcal). Default is \code{"general"}.
#' @param custom_cap_kcal Optional numeric value specifying an explicit calorie ceiling.
#'
#' @return A \code{data.frame} containing:
#' \describe{
#'   \item{energy_kcal_portion}{Reported calories per portion.}
#'   \item{guideline_kcal}{Applicable calorie guideline ceiling.}
#'   \item{excess_kcal}{Difference (\code{energy_kcal_portion - guideline_kcal}), where values > 0 indicate excess.}
#'   \item{meets_calorie_guideline}{Logical: \code{TRUE} if calories \eqn{\le} guideline.}
#' }
#'
#' @references
#' Public Health England / Office for Health Improvement and Disparities (2020).
#' \emph{Calorie reduction: criteria and guidelines for the food industry}.
#'
#' Tan M, Pham H, Pombo-Rodrigues S, et al. (2025). Nutritional composition and healthiness of out-of-home food and drink.
#' \emph{Proceedings of the Nutrition Society}, 84(OCE3), E208.
#'
#' @examples
#' # Assess a sandwich containing 620 kcal:
#' check_calorie_guideline(energy_kcal_portion = 620, category = "Sandwiches")
#'
#' # Assess main meals against the 600 kcal lunch/dinner guideline:
#' check_calorie_guideline(energy_kcal_portion = c(520, 680, 890), meal_type = "lunch")
#'
#' @export
check_calorie_guideline <- function(energy_kcal_portion,
                                    category = NULL,
                                    meal_type = c("general", "breakfast", "lunch", "dinner", "snack"),
                                    custom_cap_kcal = NULL) {
  meal_type <- match.arg(meal_type)
  n <- length(energy_kcal_portion)
  kcal <- as.numeric(energy_kcal_portion)

  guide_cap <- numeric(n)

  if (!is.null(custom_cap_kcal)) {
    guide_cap <- rep_len(as.numeric(custom_cap_kcal), n)
  } else if (!is.null(category)) {
    cat_lower <- tolower(trimws(rep_len(as.character(category), n)))
    for (i in seq_len(n)) {
      c_i <- cat_lower[i]
      if (grepl("sandwich|wrap|roll|baguette|panini", c_i)) {
        guide_cap[i] <- 550
      } else if (grepl("pizza", c_i)) {
        guide_cap[i] <- 1000
      } else if (grepl("starter|side|small plate|chip|fry|fries", c_i)) {
        guide_cap[i] <- 250
      } else if (grepl("dessert|pudding|cake|pastry|ice cream", c_i)) {
        guide_cap[i] <- 250
      } else if (grepl("main|meal|burger|curry|pie|pasta", c_i)) {
        guide_cap[i] <- 600
      } else {
        # Fallback to meal_type default
        guide_cap[i] <- switch(meal_type,
          breakfast = 400,
          lunch = 600,
          dinner = 600,
          snack = 200,
          general = 600
        )
      }
    }
  } else {
    default_val <- switch(meal_type,
      breakfast = 400,
      lunch = 600,
      dinner = 600,
      snack = 200,
      general = 600
    )
    guide_cap <- rep_len(default_val, n)
  }

  excess <- kcal - guide_cap
  meets <- (excess <= 0)

  data.frame(
    energy_kcal_portion = kcal,
    guideline_kcal = guide_cap,
    excess_kcal = excess,
    meets_calorie_guideline = meets,
    stringsAsFactors = FALSE
  )
}

/**
 * uknpm Shiny Application - Apple Design System
 * Inspired by Apple Human Interface Guidelines and world-class design systems
 */

:root {
  --color-canvas: #f5f5f7;
  --color-surface: #ffffff;
  --color-surface-translucent: rgba(255, 255, 255, 0.82);
  --color-text-primary: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-text-tertiary: #86868b;
  --color-border: rgba(0, 0, 0, 0.08);
  --color-border-subtle: rgba(0, 0, 0, 0.04);
  --color-accent: #0071e3;
  --color-accent-hover: #0077ed;
  --color-accent-light: rgba(0, 113, 227, 0.08);

  /* Status Colors */
  --color-green: #34c759;
  --color-green-bg: #e8f8ed;
  --color-green-text: #1d7335;
  --color-amber: #ff9500;
  --color-amber-bg: #fff6e6;
  --color-amber-text: #945300;
  --color-red: #ff3b30;
  --color-red-bg: #ffebeb;
  --color-red-text: #b31b14;

  /* Typography */
  --font-system: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  /* Radii */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-pill: 980px;

  /* Shadows */
  --shadow-card: 0 4px 20px -2px rgba(0, 0, 0, 0.05), 0 2px 6px -1px rgba(0, 0, 0, 0.03);
  --shadow-card-hover: 0 12px 32px -4px rgba(0, 0, 0, 0.09), 0 4px 12px -2px rgba(0, 0, 0, 0.05);
  --shadow-popover: 0 20px 40px -8px rgba(0, 0, 0, 0.15);
}

/* Base page setup */
body {
  font-family: var(--font-system);
  background-color: var(--color-canvas);
  color: var(--color-text-primary);
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  line-height: 1.5;
  letter-spacing: -0.015em;
}

/* Glassmorphism Header */
.apple-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--color-surface-translucent);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  padding: 14px 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.apple-header-title {
  display: flex;
  align-items: center;
  gap: 12px;
}

.apple-logo-badge {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: #1d1d1f;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 15px;
  letter-spacing: -0.5px;
}

.apple-header-text h1 {
  font-size: 19px;
  font-weight: 600;
  margin: 0;
  color: var(--color-text-primary);
  letter-spacing: -0.02em;
}

.apple-header-text p {
  font-size: 12px;
  font-weight: 400;
  margin: 0;
  color: var(--color-text-tertiary);
}

.apple-header-badge {
  background: var(--color-accent-light);
  color: var(--color-accent);
  padding: 4px 12px;
  border-radius: var(--radius-pill);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

/* Main Container */
.apple-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 28px 60px 28px;
}

/* Segmented Control Navigation */
.apple-nav-segmented {
  display: flex;
  background: #e5e5ea;
  padding: 3px;
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  width: fit-content;
  max-width: 100%;
}

.nav-pills .nav-link {
  font-family: var(--font-system);
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: 9px;
  padding: 8px 18px;
  margin: 0;
  border: none;
  background: transparent;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  letter-spacing: -0.01em;
}

.nav-pills .nav-link.active,
.nav-pills .nav-link:hover {
  background: #ffffff;
  color: var(--color-text-primary);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

/* Cards & Surfaces */
.apple-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-card);
  padding: 24px;
  margin-bottom: 24px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.apple-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--color-border-subtle);
  padding-bottom: 14px;
  margin-bottom: 18px;
}

.apple-card-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--color-text-primary);
  margin: 0;
  letter-spacing: -0.015em;
}

.apple-card-subtitle {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

/* Stat Metrics Grid */
.apple-metrics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}

.apple-metric-tile {
  background: var(--color-canvas);
  border-radius: var(--radius-md);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
}

.apple-metric-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-tertiary);
  margin-bottom: 4px;
}

.apple-metric-value {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--color-text-primary);
  line-height: 1.1;
}

.apple-metric-subtext {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}

/* Traffic Light Pills / Status Badges */
.badge-hfss {
  background: var(--color-red-bg);
  color: var(--color-red-text);
  border: 1px solid rgba(255, 59, 48, 0.2);
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.badge-healthy {
  background: var(--color-green-bg);
  color: var(--color-green-text);
  border: 1px solid rgba(52, 199, 89, 0.2);
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* Front-of-Pack Traffic Light Lozenge Set */
.mtl-lozenge-container {
  display: flex;
  gap: 10px;
  justify-content: center;
  margin: 16px 0;
  flex-wrap: wrap;
}

.mtl-lozenge {
  flex: 1;
  min-width: 85px;
  max-width: 120px;
  border-radius: 12px;
  padding: 10px 8px;
  text-align: center;
  border: 1px solid rgba(0,0,0,0.06);
  box-shadow: 0 2px 6px rgba(0,0,0,0.04);
}

.mtl-lozenge-nutrient {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 2px;
  letter-spacing: 0.03em;
}

.mtl-lozenge-amount {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.1;
}

.mtl-lozenge-unit {
  font-size: 10px;
