}

.mtl-lozenge-traffic {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  margin-top: 4px;
  padding: 2px 6px;
  border-radius: 4px;
  letter-spacing: 0.04em;
}

.mtl-green {
  background: var(--color-green-bg);
  color: var(--color-green-text);
}
